{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Ribavirin, a highly polar D-ribosyl azole carboxamide closely related to the query, has an absolute oral bioavailability of 44.6% ± 2.1% in humans, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Levovirin, the L-ribose enantiomer of ribavirin, has human oral bioavailability <10%, but its L-configuration reduces transferability to the D-ribose query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Fludarabine phosphate, a polar purine nucleoside, shows ~55% systemic availability after oral tablets in patients, supporting high F for polar nucleoside analogs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Clofarabine, another polar nucleoside, has oral bioavailability of 57.5% in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Uridine, an endogenous pyrimidine riboside, has only ~7% oral bioavailability in humans, but this low value is confounded by extensive first-pass metabolism and is less transferable to the imidazole carboxamide query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a D-ribosyl imidazole carboxamide (mizoribine-like) with high polarity; the closest relevant experimental anchor is ribavirin, whose human absolute F is ~45-50%, and other polar nucleosides (fludarabine, clofarabine) also exceed 20%. Low-F analogues are either L-ribose (levovirin) or endogenous/metabolically labile (uridine) and transfer less well. Therefore high F is better supported despite the unfavorable physicochemical prior.",
  "evidence_gaps": [
    "No direct experimental F measurement for mizoribine/query itself is included in the provided evidence; transporter affinity and metabolic stability of the 5-hydroxyimidazole carboxamide are inferred from analogues.",
    "Ribavirin F varies by population and dose, with some records below 20% in children, adding uncertainty to the quantitative threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

